UPDATE public.products
SET price = CASE id
  WHEN 'a0000000-0000-4000-8000-000000000001'::uuid THEN 299.00
  WHEN 'a0000000-0000-4000-8000-000000000002'::uuid THEN 199.00
  WHEN 'a0000000-0000-4000-8000-000000000003'::uuid THEN 499.00
  ELSE price
END
WHERE id IN (
  'a0000000-0000-4000-8000-000000000001'::uuid,
  'a0000000-0000-4000-8000-000000000002'::uuid,
  'a0000000-0000-4000-8000-000000000003'::uuid
);
